package io.github.ericonyu.qimen4kotlin
import com.google.gson.Gson;import java.nio.file.Files;import java.nio.file.StandardCopyOption
object Qimen{private val gson=Gson();private val engine by lazy{val p=Files.createTempFile("qimen-engine-",".cjs");javaClass.getResourceAsStream("/engine.cjs")!!.use{Files.copy(it,p,StandardCopyOption.REPLACE_EXISTING)};p.toFile().deleteOnExit();p};fun calculate(input:Map<String,Any>):Map<String,Any>{val p=ProcessBuilder("node",engine.toString()).start();p.outputStream.bufferedWriter().use{it.write(gson.toJson(input))};val stdout=p.inputStream.bufferedReader().readText();val stderr=p.errorStream.bufferedReader().readText();val code=p.waitFor();val env=gson.fromJson(stdout,Map::class.java) as Map<String,Any>;if(code!=0||env["ok"]!=true)error(env["error"]?.toString()?:stderr);return env["data"] as Map<String,Any>}}
